package compare

import (
	"fmt"
	"math"

	"repro-verify/internal/mlck"
)

type DiffHistogram struct {
	Exact   int `json:"exact"`
	Less1e7 int `json:"<1e-7"`
	Less1e5 int `json:"<1e-5"`
	Less1e3 int `json:"<1e-3"`
	Less1   int `json:"<1"`
	Geq1    int `json:">=1"`
}

type TensorResult struct {
	Name          string        `json:"name"`
	Match         bool          `json:"match"`
	MaxAbsDiff    float64       `json:"max_abs_diff"`
	MaxRelDiff    float64       `json:"max_rel_diff"`
	NumMismatches int           `json:"num_mismatches"`
	TotalElements int           `json:"total_elements"`
	ShapeMismatch bool          `json:"shape_mismatch"`
	DiffHistogram *DiffHistogram `json:"diff_histogram,omitempty"`
}

type Result struct {
	Match          bool           `json:"match"`
	Mode           string         `json:"mode"`
	Atol           float64        `json:"atol"`
	Rtol           float64        `json:"rtol"`
	HistogramEnabled bool         `json:"histogram_enabled,omitempty"`
	TensorResults  []TensorResult `json:"tensor_results"`
	MissingInFile1 []string       `json:"missing_in_file1"`
	MissingInFile2 []string       `json:"missing_in_file2"`
	Error          string         `json:"error,omitempty"`
}

func Compare(c1, c2 *mlck.Checkpoint, mode string, atol, rtol float64, histogram bool) (*Result, error) {
	if mode != "strict" && mode != "relaxed" {
		return nil, fmt.Errorf("invalid mode %q", mode)
	}

	result := &Result{
		Match:            true,
		Mode:             mode,
		Atol:             atol,
		Rtol:             rtol,
		HistogramEnabled: histogram,
		TensorResults:    []TensorResult{},
		MissingInFile1:   []string{},
		MissingInFile2:   []string{},
	}

	map2 := make(map[string]mlck.Tensor)
	for _, t := range c2.Tensors {
		map2[t.Name] = t
	}
	map1 := make(map[string]mlck.Tensor)
	for _, t := range c1.Tensors {
		map1[t.Name] = t
	}

	for _, t1 := range c1.Tensors {
		t2, ok := map2[t1.Name]
		if !ok {
			result.MissingInFile2 = append(result.MissingInFile2, t1.Name)
			continue
		}
		tr := compareTensors(t1, t2, mode, atol, rtol, histogram)
		result.TensorResults = append(result.TensorResults, tr)
		if !tr.Match {
			result.Match = false
		}
	}

	for _, t := range c2.Tensors {
		if _, ok := map1[t.Name]; !ok {
			result.MissingInFile1 = append(result.MissingInFile1, t.Name)
		}
	}

	if len(result.MissingInFile1) > 0 || len(result.MissingInFile2) > 0 {
		result.Match = false
	}

	return result, nil
}

func compareTensors(t1, t2 mlck.Tensor, mode string, atol, rtol float64, histogram bool) TensorResult {
	total := int(mlck.Product(t1.Shape))

	tr := TensorResult{
		Name:          t1.Name,
		Match:         true,
		MaxAbsDiff:    0,
		MaxRelDiff:    0,
		NumMismatches: 0,
		TotalElements: total,
	}

	if !shapesEqual(t1.Shape, t2.Shape) {
		tr.Match = false
		tr.ShapeMismatch = true
		tr.NumMismatches = total
		return tr
	}

	if total == 0 {
		if histogram {
			tr.DiffHistogram = &DiffHistogram{}
		}
		return tr
	}

	vals1, err := t1.Float64Values()
	if err != nil {
		tr.Match = false
		tr.NumMismatches = total
		return tr
	}
	vals2, err := t2.Float64Values()
	if err != nil {
		tr.Match = false
		tr.NumMismatches = total
		return tr
	}

	var hist DiffHistogram
	threshold := int(math.Floor(float64(total) * 0.001))
	for i := 0; i < total; i++ {
		a := vals1[i]
		b := vals2[i]
		diff := math.Abs(a - b)
		if diff > tr.MaxAbsDiff {
			tr.MaxAbsDiff = diff
		}
		var rel float64
		if math.Abs(b) > 0 {
			rel = diff / math.Abs(b)
		} else if diff > 0 {
			rel = diff
		}
		if rel > tr.MaxRelDiff {
			tr.MaxRelDiff = rel
		}
		if diff > atol+rtol*math.Abs(b) {
			tr.NumMismatches++
		}

		switch {
		case diff == 0:
			hist.Exact++
		case diff < 1e-7:
			hist.Less1e7++
		case diff < 1e-5:
			hist.Less1e5++
		case diff < 1e-3:
			hist.Less1e3++
		case diff < 1:
			hist.Less1++
		default:
			hist.Geq1++
		}
	}

	if histogram {
		tr.DiffHistogram = &hist
	}

	switch mode {
	case "strict":
		tr.Match = tr.NumMismatches == 0
	case "relaxed":
		tr.Match = tr.NumMismatches <= threshold
	}

	return tr
}

func shapesEqual(a, b []uint32) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
